package com.rikkeibank.account.model; import jakarta.persistence.*; import java.io.Serializable;
@Entity @Table(name="account_types") public class AccountType implements Serializable{private static final long serialVersionUID=1L;@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String code;@Column(nullable=false) private String name;private String description;private boolean active=true;public Long getId(){return id;}public void setId(Long v){id=v;}public String getCode(){return code;}public void setCode(String v){code=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
